@startuml

class SensorController {
}

class Apartment {
  +address : string
  +email : string
}

class Inhabitant {
  +username : string
  +password : string
}

class Administrator extends Inhabitant {
}

class Room {
  +description : string
}

class Sensor {
  +vendorId : string
  +description : string
  +unit : Unit
  +threshold : double
}

abstract class SensorType {}

class TemperatureSensor extends SensorType {
  +min : double
  +max : double
}

class PowerSensor extends SensorType {
  +counterReading : double
}

class MeasuredValue {
  +timestamp : datetime
  +value : double
}

class EMonitor {}

enum Unit {
  CELSIUS
  WATT
}

SensorController "1" *-- "1" Apartment
Apartment "1" *-- "2..*" Room
Apartment "1" *-- "*" Inhabitant
Apartment "1" *-- "*" Sensor
Inhabitant "1" -- "*" Sensor : queries
Administrator "1" -- "*" Sensor : configures
Room "1" *-- "1" Sensor
Sensor "1" *-- "*" MeasuredValue
Sensor "1" --> "0..1" MeasuredValue : last value
EMonitor "1" ..> SensorController : checks thresholds

@enduml

